pragma solidity >=0.4.22 <0.9.0;

contract SecureVoting {
    address public admin;

    enum ElectionState { NotStarted, Active, Ended }
    ElectionState public electionState;

    struct Candidate {
        uint256 id;
        string name;
        uint256 voteCount;
    }

    // Save who has voted
    mapping(address => bool) public voters;

    // Read/Write candidates
    mapping(uint256 => Candidate) public candidates;

    // Used to access to the candidates mapping
    uint256 public candidateCount;

    // Events
    event CandidateAdded(uint256 candidateId, string name);
    event ElectionStarted();
    event ElectionEnded();
    event VoteCast(address indexed voter, uint256 indexed candidateId);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Only administrator can perform this action");
        _;
    }

    modifier onlyActive() {
        require(electionState == ElectionState.Active, "Election is not active");
        _;
    }

    constructor() public {
        admin = msg.sender;
        electionState = ElectionState.NotStarted;
    }

    function addCandidate(string memory _name) public onlyAdmin {
        require(electionState == ElectionState.NotStarted, "Cannot add candidates after election has started");
        candidateCount++;
        candidates[candidateCount] = Candidate(candidateCount, _name, 0);
        emit CandidateAdded(candidateCount, _name);
    }

    function startElection() public onlyAdmin {
        require(electionState == ElectionState.NotStarted, "Election is already active or ended");
        electionState = ElectionState.Active;
        emit ElectionStarted();
    }

    function endElection() public onlyAdmin {
        require(electionState == ElectionState.Active, "Election is not active");
        electionState = ElectionState.Ended;
        emit ElectionEnded();
    }

    function vote(uint256 _candidateId) public onlyActive {
        // An address can vote only once
        require(!voters[msg.sender], "Voter has already voted");

        // Vote for a valid candidate
        require(_candidateId > 0 && _candidateId <= candidateCount, "Invalid candidate");

        // Has voted
        voters[msg.sender] = true;

        // Apply the vote in the candidate count
        candidates[_candidateId].voteCount++;

        // Trigger vote event
        emit VoteCast(msg.sender, _candidateId);
    }
}
